{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C71"],
      "claim": "Verapamil, a structurally closest analogue with two dimethoxyphenyl groups and a tertiary amine, has an average absolute oral bioavailability of 19.4% in healthy young men after single oral doses, indicating extensive first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Verapamil oral bioavailability is approximately 20%, attributed to extensive first-pass metabolism, supporting a borderline-low F for the verapamil-like query scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Verapamil bioavailability was 18–20% across different oral doses in normal subjects, directly supporting F below or at the 20% threshold for a closely related analogue.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Levosulpiride, a related dimethoxybenzamide weak base with a basic amine, has oral bioavailability of ~30%, but its absorption is slow and incomplete; this supports low-to-borderline oral bioavailability for similar ionizable lipophilic amines.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Levosulpiride oral bioavailability was only 23.4% compared with 96.8% IM, demonstrating that a structurally related dimethoxyphenyl amine can have low oral systemic availability due to incomplete absorption and first-pass effects.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Encainide, another lipophilic basic drug with extensive first-pass metabolism, has oral bioavailability of 32 ± 7% in normal subjects, but with wide interindividual variability and low values in many patients, supporting the first-pass liability of this compound class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Alfentanil, a lipophilic basic drug with high hepatic extraction, has oral bioavailability of 0.45 ± 0.09 in control subjects, illustrating that lipophilic weak bases with high first-pass metabolism often have F below 50% and sometimes below 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a verapamil-like lipophilic weak base with two dimethoxyphenyl motifs and a tertiary amine; the closest analogue verapamil has F around 18–35% with many values near 20%, and related basic lipophilic drugs show low oral bioavailability due to first-pass metabolism and incomplete absorption. No evidence supports high F, so the prediction is low (F < 20%).",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the exact query molecule.",
    "The query contains a lactam and a chiral tetralin-like motif not present in the closest analogue verapamil; their effect on first-pass metabolism is uncertain.",
    "Most analogue records are from healthy subjects or patients with altered hepatic function; the query's behavior in the relevant target population is unknown."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "high",
